package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

// ============================================================
// 数据模型
// ============================================================

// ContactInfo 联系人信息
type ContactInfo struct {
	Name         string    `json:"name"`
	IP           string    `json:"ip"`
	WSPort       int       `json:"ws_port"`
	FirstContact string    `json:"first_contact"`
	LastContact  string    `json:"last_contact"`
	Messages     []Message `json:"messages"`
	Trusted      bool      `json:"trusted"`
}

// ContactSummary 联系人摘要（不含 messages）
type ContactSummary struct {
	UUID         string `json:"uuid"`
	Name         string `json:"name"`
	IP           string `json:"ip"`
	WSPort       int    `json:"ws_port"`
	FirstContact string `json:"first_contact"`
	LastContact  string `json:"last_contact"`
	Trusted      bool   `json:"trusted"`
	MessageCount int    `json:"message_count"`
}

// Message 聊天/文件消息
type Message struct {
	From       string `json:"from"`
	Content    string `json:"content"`
	MsgID      string `json:"msg_id"`
	Type       string `json:"type"` // "chat" | "file"
	Timestamp  string `json:"timestamp"`
	FileName   string `json:"file_name,omitempty"`
	FileSize   int64  `json:"file_size,omitempty"`
	TransferID string `json:"transfer_id,omitempty"`
	Status     string `json:"status,omitempty"`
	Progress   int    `json:"progress,omitempty"`
}

// ProgressInfo 传输进度信息
type ProgressInfo struct {
	FileName       string `json:"file_name"`
	FileSize       int64  `json:"file_size"`
	ChunkSize      int    `json:"chunk_size"`
	ReceivedChunks []int  `json:"received_chunks"`
	ReceivedBytes  int64  `json:"received_bytes"`
	TotalChunks    int    `json:"total_chunks"`
	FromUUID       string `json:"from_uuid"`
	FromName       string `json:"from_name"`
	Status         string `json:"status"`
	CreatedAt      string `json:"created_at"`
	LastUpdate     string `json:"last_update"`
}

// ============================================================
// Storage 存储管理器
// ============================================================

// Storage 线程安全的 JSON 文件持久化管理器
type Storage struct {
	dataDir       string
	configPath    string
	contactsPath  string
	downloadsDir  string
	configLock    sync.Mutex
	contactsLock  sync.Mutex
}

// NewStorage 创建存储管理器
func NewStorage(dataDir string) *Storage {
	s := &Storage{
		dataDir:      dataDir,
		configPath:   filepath.Join(dataDir, "config.json"),
		contactsPath: filepath.Join(dataDir, "contacts.json"),
		downloadsDir: filepath.Join(dataDir, "downloads"),
	}
	s.ensureDataDir()
	return s
}

// ensureDataDir 确保数据目录存在
func (s *Storage) ensureDataDir() {
	os.MkdirAll(s.dataDir, 0755)
	os.MkdirAll(s.downloadsDir, 0755)
}

// ============================================================
// 配置读写
// ============================================================

// LoadConfig 读取本机配置
func (s *Storage) LoadConfig() map[string]any {
	s.ensureDataDir()
	s.configLock.Lock()
	defer s.configLock.Unlock()

	data, err := os.ReadFile(s.configPath)
	if err != nil {
		return make(map[string]any)
	}

	var config map[string]any
	if err := json.Unmarshal(data, &config); err != nil {
		return make(map[string]any)
	}
	return config
}

// SaveConfig 保存本机配置
func (s *Storage) SaveConfig(config map[string]any) {
	s.ensureDataDir()
	s.configLock.Lock()
	defer s.configLock.Unlock()

	data, _ := json.MarshalIndent(config, "", "  ")
	os.WriteFile(s.configPath, data, 0644)
}

// ============================================================
// 联系人读写
// ============================================================

// loadContactsUnsafe 读取全部联系人数据（不加锁，调用方需持有 contactsLock）
func (s *Storage) loadContactsUnsafe() map[string]*ContactInfo {
	s.ensureDataDir()
	data, err := os.ReadFile(s.contactsPath)
	if err != nil {
		return make(map[string]*ContactInfo)
	}

	var contacts map[string]*ContactInfo
	if err := json.Unmarshal(data, &contacts); err != nil {
		return make(map[string]*ContactInfo)
	}
	return contacts
}

// saveContactsUnsafe 保存全部联系人数据（不加锁，调用方需持有 contactsLock）
func (s *Storage) saveContactsUnsafe(contacts map[string]*ContactInfo) {
	s.ensureDataDir()
	data, _ := json.MarshalIndent(contacts, "", "  ")
	os.WriteFile(s.contactsPath, data, 0644)
}

// LoadContacts 读取全部联系人数据（线程安全）
func (s *Storage) LoadContacts() map[string]*ContactInfo {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()
	return s.loadContactsUnsafe()
}

// SaveContacts 保存全部联系人数据（线程安全）
func (s *Storage) SaveContacts(contacts map[string]*ContactInfo) {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()
	s.saveContactsUnsafe(contacts)
}

// GetContact 获取单个联系人信息
func (s *Storage) GetContact(uuid string) *ContactInfo {
	contacts := s.LoadContacts()
	return contacts[uuid]
}

// UpsertContact 添加或更新联系人基本信息（不覆盖 messages）
func (s *Storage) UpsertContact(uuid, name, ip string, wsPort int) {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()

	contacts := s.loadContactsUnsafe()
	now := time.Now().Format(time.RFC3339)

	if existing, ok := contacts[uuid]; !ok {
		contacts[uuid] = &ContactInfo{
			Name:         name,
			IP:           ip,
			WSPort:       wsPort,
			FirstContact: now,
			LastContact:  now,
			Messages:     []Message{},
			Trusted:      true,
		}
	} else {
		existing.Name = name
		existing.IP = ip
		existing.WSPort = wsPort
		existing.LastContact = now
		existing.Trusted = true // 重连后恢复信任
		if existing.Messages == nil {
			existing.Messages = []Message{}
		}
	}

	s.saveContactsUnsafe(contacts)
}

// AppendMessage 向指定联系人的消息列表追加或更新消息（msg_id 去重）
func (s *Storage) AppendMessage(uuid, sender, content, msgID, msgType string, extra map[string]any) {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()

	contacts := s.loadContactsUnsafe()

	if _, ok := contacts[uuid]; !ok {
		contacts[uuid] = &ContactInfo{
			Name:         "Unknown",
			IP:           "",
			FirstContact: time.Now().Format(time.RFC3339),
			LastContact:  "",
			Messages:     []Message{},
			Trusted:      true,
		}
	}

	c := contacts[uuid]
	now := time.Now().Format(time.RFC3339)

	// 查找是否已有同 msg_id 的消息
	existingIdx := -1
	for i, m := range c.Messages {
		if m.MsgID == msgID {
			existingIdx = i
			break
		}
	}

	if existingIdx >= 0 {
		if msgType == "file" {
			// 文件消息：更新状态和进度
			msg := &c.Messages[existingIdx]
			if v, ok := extra["status"]; ok {
				msg.Status = v.(string)
			}
			if v, ok := extra["progress"]; ok {
				msg.Progress = v.(int)
			}
			if v, ok := extra["file_size"]; ok {
				msg.FileSize = v.(int64)
			}
			if v, ok := extra["file_name"]; ok {
				msg.FileName = v.(string)
			}
			if v, ok := extra["transfer_id"]; ok {
				msg.TransferID = v.(string)
			}
			if extra["status"] == "complete" {
				msg.Progress = 100
			}
		}
		// chat 消息已存在则跳过（去重）
		c.LastContact = now
		s.saveContactsUnsafe(contacts)
		return
	}

	// 新消息
	msg := Message{
		From:      sender,
		Content:   content,
		MsgID:     msgID,
		Type:      msgType,
		Timestamp: now,
	}

	if msgType == "file" {
		if v, ok := extra["file_name"]; ok {
			msg.FileName = v.(string)
		}
		if v, ok := extra["file_size"]; ok {
			switch val := v.(type) {
			case int64:
				msg.FileSize = val
			case float64:
				msg.FileSize = int64(val)
			}
		}
		if v, ok := extra["transfer_id"]; ok {
			msg.TransferID = v.(string)
		}
		if v, ok := extra["status"]; ok {
			msg.Status = v.(string)
		} else {
			msg.Status = "pending"
		}
		if v, ok := extra["progress"]; ok {
			switch val := v.(type) {
			case int:
				msg.Progress = val
			case float64:
				msg.Progress = int(val)
			}
		}
	}

	c.Messages = append(c.Messages, msg)
	c.LastContact = now
	s.saveContactsUnsafe(contacts)
}

// GetMessages 获取指定联系人的聊天记录
func (s *Storage) GetMessages(uuid string) []Message {
	contact := s.GetContact(uuid)
	if contact != nil {
		return contact.Messages
	}
	return []Message{}
}

// MarkContactUntrusted 将联系人标记为不可信
func (s *Storage) MarkContactUntrusted(uuid string) {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()

	contacts := s.loadContactsUnsafe()
	if c, ok := contacts[uuid]; ok {
		c.Trusted = false
		s.saveContactsUnsafe(contacts)
	}
}

// DeleteContact 删除指定联系人及其聊天记录
func (s *Storage) DeleteContact(uuid string) {
	s.contactsLock.Lock()
	defer s.contactsLock.Unlock()

	contacts := s.loadContactsUnsafe()
	delete(contacts, uuid)
	s.saveContactsUnsafe(contacts)
}

// ListContacts 返回联系人列表（不含 messages）
func (s *Storage) ListContacts() []ContactSummary {
	contacts := s.LoadContacts()
	result := make([]ContactSummary, 0, len(contacts))

	for uuid, info := range contacts {
		result = append(result, ContactSummary{
			UUID:         uuid,
			Name:         info.Name,
			IP:           info.IP,
			WSPort:       info.WSPort,
			FirstContact: info.FirstContact,
			LastContact:  info.LastContact,
			Trusted:      info.Trusted,
			MessageCount: len(info.Messages),
		})
	}

	// 按最后联系时间倒序
	sortByLastContact(result)
	return result
}

// sortByLastContact 按 last_contact 降序排列（最近联系人排前）
func sortByLastContact(contacts []ContactSummary) {
	for i := 0; i < len(contacts); i++ {
		for j := i + 1; j < len(contacts); j++ {
			if contacts[j].LastContact > contacts[i].LastContact {
				contacts[i], contacts[j] = contacts[j], contacts[i]
			}
		}
	}
}

// ============================================================
// 传输进度文件
// ============================================================

// SaveProgress 保存传输进度文件
func (s *Storage) SaveProgress(transferID string, progress *ProgressInfo) {
	s.ensureDataDir()
	path := filepath.Join(s.downloadsDir, transferID+".progress")
	data, _ := json.MarshalIndent(progress, "", "  ")
	os.WriteFile(path, data, 0644)
}

// LoadProgress 读取传输进度文件
func (s *Storage) LoadProgress(transferID string) *ProgressInfo {
	path := filepath.Join(s.downloadsDir, transferID+".progress")
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}

	var progress ProgressInfo
	if err := json.Unmarshal(data, &progress); err != nil {
		return nil
	}
	return &progress
}

// DeleteProgress 删除传输进度文件和对应的临时文件
func (s *Storage) DeleteProgress(transferID string) {
	// 删除 .progress 文件
	progressPath := filepath.Join(s.downloadsDir, transferID+".progress")
	os.Remove(progressPath)

	// 删除对应的 .part 文件
	entries, _ := os.ReadDir(s.downloadsDir)
	for _, entry := range entries {
		if strings.HasSuffix(entry.Name(), ".part") && strings.HasPrefix(entry.Name(), transferID) {
			os.Remove(filepath.Join(s.downloadsDir, entry.Name()))
		}
	}
}

// GetDownloadPath 获取下载文件路径，自动处理同名冲突，防止路径穿越
func (s *Storage) GetDownloadPath(fileName string) (string, error) {
	s.ensureDataDir()

	// 第一层防御：只取文件名部分
	safeName := filepath.Base(fileName)
	target, err := filepath.EvalSymlinks(filepath.Join(s.downloadsDir, safeName))
	if err != nil {
		// 文件不存在时 EvalSymlinks 会报错，使用 Clean 代替
		target = filepath.Clean(filepath.Join(s.downloadsDir, safeName))
	}

	// 第二层防御：检查路径必须在 downloads 目录内
	allowedBase, _ := filepath.EvalSymlinks(s.downloadsDir)
	if allowedBase == "" {
		allowedBase, _ = filepath.Abs(s.downloadsDir)
	}
	if !strings.HasPrefix(target, allowedBase) {
		return "", os.ErrPermission
	}

	// 无冲突直接返回
	if _, err := os.Stat(target); os.IsNotExist(err) {
		return target, nil
	}

	// 同名冲突：file(1).ext, file(2).ext ...
	ext := filepath.Ext(safeName)
	stem := safeName[:len(safeName)-len(ext)]
	counter := 1
	for {
		newName := stem + "(" + itoa(counter) + ")" + ext
		candidate := filepath.Join(s.downloadsDir, newName)
		if _, err := os.Stat(candidate); os.IsNotExist(err) {
			return candidate, nil
		}
		counter++
	}
}

// CleanupExpiredProgress 清理过期进度文件
func (s *Storage) CleanupExpiredProgress(maxAgeHours int) {
	threshold := time.Now().Add(-time.Duration(maxAgeHours) * time.Hour)

	entries, err := os.ReadDir(s.downloadsDir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		if !strings.HasSuffix(entry.Name(), ".progress") {
			continue
		}
		path := filepath.Join(s.downloadsDir, entry.Name())
		data, err := os.ReadFile(path)
		if err != nil {
			os.Remove(path)
			continue
		}

		var progress ProgressInfo
		if err := json.Unmarshal(data, &progress); err != nil {
			os.Remove(path)
			continue
		}

		lastUpdate, err := time.Parse(time.RFC3339, progress.LastUpdate)
		if err != nil {
			// 尝试其他格式
			lastUpdate, err = time.Parse("2006-01-02T15:04:05", progress.LastUpdate)
			if err != nil {
				os.Remove(path)
				continue
			}
		}

		if lastUpdate.Before(threshold) {
			transferID := entry.Name()[:len(entry.Name())-len(".progress")]
			s.DeleteProgress(transferID)
		}
	}
}

// ============================================================
// 工具函数
// ============================================================

func itoa(n int) string {
	return strings.TrimRight(strings.TrimRight(
		formatInt(n), "0"), ".")
}

func formatInt(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

