package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

// ============================================================
// 常量
// ============================================================

const (
	broadcastPort    = 50001
	heartbeatInterval = 3 * time.Second
	peerTimeout       = 10 * time.Second
	missThreshold     = 3
	cacheTTL          = 60 * time.Second
)

// ============================================================
// TokenManager
// ============================================================

// TokenManager 管理本机的会话 Token，每3秒自动刷新
type TokenManager struct {
	mu        sync.Mutex
	current   string
	previous  string
	createdAt time.Time
}

// NewTokenManager 创建 TokenManager
func NewTokenManager() *TokenManager {
	tm := &TokenManager{}
	tm.refresh()
	return tm
}

// refresh 生成新的随机 token（不加锁，调用方需持有 mu）
func (tm *TokenManager) refresh() {
	tm.previous = tm.current
	b := make([]byte, 16)
	rand.Read(b)
	tm.current = hex.EncodeToString(b)
	tm.createdAt = time.Now()
}

// GetToken 获取当前 token，超过间隔则自动刷新
func (tm *TokenManager) GetToken() string {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	if time.Since(tm.createdAt) > heartbeatInterval {
		tm.refresh()
	}
	return tm.current
}

// ============================================================
// PeerInfo 在线节点信息
// ============================================================

// PeerInfo 节点信息
type PeerInfo struct {
	UUID          string  `json:"uuid"`
	Name          string  `json:"name"`
	IP            string  `json:"ip"`
	WSPort        int     `json:"ws_port"`
	Token         string  `json:"token"`
	PreviousToken string  `json:"-"`
	LastSeen      float64 `json:"last_seen"`
	MissCount     int     `json:"-"`
	Status        string  `json:"status"` // "online" | "offline"
}

// ============================================================
// BroadcastInterface
// ============================================================

// BroadcastInterface 广播地址和对应的网卡 IP
type BroadcastInterface struct {
	BroadcastAddr string
	InterfaceIP   string
}

// ============================================================
// Discovery
// ============================================================

// Discovery 节点发现服务
type Discovery struct {
	myUUID   string
	myName   string
	myIP     string
	wsPort   int
	tokenMgr *TokenManager

	peers   map[string]*PeerInfo
	peersMu sync.RWMutex

	running atomic.Bool
	conn    *net.UDPConn

	// 事件回调（线程安全，通过 channel 转发）
	eventChan      chan PeerEvent
	onPeerOnline   func(*PeerInfo)
	onPeerOffline  func(*PeerInfo)
}

// PeerEvent 节点事件
type PeerEvent struct {
	Online bool
	Peer   *PeerInfo
}

// NewDiscovery 创建节点发现服务
func NewDiscovery(myUUID, myName, myIP string, wsPort int, tokenMgr *TokenManager) *Discovery {
	return &Discovery{
		myUUID:    myUUID,
		myName:    myName,
		myIP:      myIP,
		wsPort:    wsPort,
		tokenMgr:  tokenMgr,
		peers:     make(map[string]*PeerInfo),
		eventChan: make(chan PeerEvent, 64),
	}
}

// SetCallbacks 设置事件回调
func (d *Discovery) SetCallbacks(onOnline, onOffline func(*PeerInfo)) {
	d.onPeerOnline = onOnline
	d.onPeerOffline = onOffline
}

// Start 启动发现服务
func (d *Discovery) Start() error {
	addr := &net.UDPAddr{
		IP:   net.IPv4zero,
		Port: broadcastPort,
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		return err
	}
	d.conn = conn
	d.running.Store(true)

	// 启动时立即发一次广播
	d.broadcastHeartbeat()

	// 启动事件转发 goroutine
	go d.eventForwarder()

	// 启动广播 goroutine
	go d.broadcastLoop()

	// 启动监听 goroutine
	go d.listenLoop()

	return nil
}

// Stop 停止发现服务
func (d *Discovery) Stop() {
	d.running.Store(false)

	// 发送 goodbye 广播
	interfaces := getBroadcastInterfaces()
	goodbye, _ := json.Marshal(map[string]string{
		"type": "goodbye",
		"uuid": d.myUUID,
	})
	for _, iface := range interfaces {
		addr := &net.UDPAddr{IP: net.ParseIP(iface.BroadcastAddr), Port: broadcastPort}
		d.conn.WriteToUDP(goodbye, addr)
	}

	if d.conn != nil {
		d.conn.Close()
	}
}

// GetPeers 获取当前在线节点列表
func (d *Discovery) GetPeers() []PeerInfo {
	d.peersMu.RLock()
	defer d.peersMu.RUnlock()

	result := make([]PeerInfo, 0)
	for _, p := range d.peers {
		if p.Status == "online" {
			result = append(result, *p)
		}
	}
	return result
}

// GetAllPeers 获取所有已知节点列表（含离线）
func (d *Discovery) GetAllPeers() []PeerInfo {
	d.peersMu.RLock()
	defer d.peersMu.RUnlock()

	result := make([]PeerInfo, 0, len(d.peers))
	for _, p := range d.peers {
		result = append(result, *p)
	}
	return result
}

// GetPeer 获取指定节点信息
func (d *Discovery) GetPeer(uuid string) *PeerInfo {
	d.peersMu.RLock()
	defer d.peersMu.RUnlock()

	if p, ok := d.peers[uuid]; ok {
		cp := *p
		return &cp
	}
	return nil
}

// VerifyToken 验证某个 uuid 提供的 token 是否与记录匹配
func (d *Discovery) VerifyToken(uuid, token string) bool {
	d.peersMu.RLock()
	defer d.peersMu.RUnlock()

	peer, ok := d.peers[uuid]
	if !ok {
		return false
	}
	return token == peer.Token || token == peer.PreviousToken
}

// ============================================================
// 内部方法
// ============================================================

func (d *Discovery) broadcastHeartbeat() {
	interfaces := getBroadcastInterfaces()

	for _, iface := range interfaces {
		ip := iface.InterfaceIP
		if ip == "0.0.0.0" {
			ip = d.myIP
		}

		msg, _ := json.Marshal(map[string]any{
			"type":      "hello",
			"uuid":      d.myUUID,
			"name":      d.myName,
			"ip":        ip,
			"ws_port":   d.wsPort,
			"token":     d.tokenMgr.GetToken(),
			"timestamp": float64(time.Now().UnixMilli()) / 1000.0,
		})

		addr := &net.UDPAddr{IP: net.ParseIP(iface.BroadcastAddr), Port: broadcastPort}
		d.conn.WriteToUDP(msg, addr)
	}
}

func (d *Discovery) broadcastLoop() {
