			}
		}
	}
}

func (d *Discovery) checkTimeouts() {
	now := float64(time.Now().UnixMilli()) / 1000.0

	d.peersMu.Lock()
	var offlinePeers []PeerInfo
	for _, peer := range d.peers {
		if peer.Status != "online" {
			continue
		}
