				if !ok || ipNet.IP.To4() == nil || ipNet.IP.IsLoopback() {
					continue
				}

				// 计算广播地址
				bcast := make(net.IP, 4)
				for i := 0; i < 4; i++ {
					bcast[i] = ipNet.IP.To4()[i] | ^ipNet.Mask[i]
				}

				interfaces = append(interfaces, BroadcastInterface{
					BroadcastAddr: bcast.String(),
					InterfaceIP:   ipNet.IP.String(),
				})
			}
		}
	}

	// 兜底：255.255.255.255
	if len(interfaces) == 0 {
		interfaces = append(interfaces, BroadcastInterface{
			BroadcastAddr: "255.255.255.255",
			InterfaceIP:   "0.0.0.0",
		})
	}

	cachedInterfaces = interfaces
	cachedInterfacesTime = time.Now()
	return interfaces
}

