// ============================================================
// 常量
// ============================================================

const (
	broadcastPort    = 50001
	heartbeatInterval = 3 * time.Second
	peerTimeout       = 10 * time.Second
	missThreshold     = 3
	cacheTTL          = 60 * time.Second
)

// ============================================================
// TokenManager
// ============================================================

// TokenManager 管理本机的会话 Token，每3秒自动刷新
type TokenManager struct {
	mu        sync.Mutex
	current   string
	previous  string
	createdAt time.Time
}

// NewTokenManager 创建 TokenManager
func NewTokenManager() *TokenManager {
	tm := &TokenManager{}
	tm.refresh()
	return tm
}

// refresh 生成新的随机 token（不加锁，调用方需持有 mu）
func (tm *TokenManager) refresh() {
	tm.previous = tm.current
	b := make([]byte, 16)
	rand.Read(b)
	tm.current = hex.EncodeToString(b)
	tm.createdAt = time.Now()
}

// GetToken 获取当前 token，超过间隔则自动刷新
func (tm *TokenManager) GetToken() string {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	if time.Since(tm.createdAt) > heartbeatInterval {
		tm.refresh()
	}
	return tm.current
