// ============================================================
// Discovery
// ============================================================

// Discovery 节点发现服务
type Discovery struct {
	myUUID   string
	myName   string
	myIP     string
	wsPort   int
	tokenMgr *TokenManager

	peers   map[string]*PeerInfo
	peersMu sync.RWMutex

	running atomic.Bool
	conn    *net.UDPConn

	// 事件回调（线程安全，通过 channel 转发）
	eventChan      chan PeerEvent
	onPeerOnline   func(*PeerInfo)
	onPeerOffline  func(*PeerInfo)
}

// PeerEvent 节点事件
type PeerEvent struct {
	Online bool
	Peer   *PeerInfo
}

// NewDiscovery 创建节点发现服务
func NewDiscovery(myUUID, myName, myIP string, wsPort int, tokenMgr *TokenManager) *Discovery {
	return &Discovery{
		myUUID:    myUUID,
		myName:    myName,
		myIP:      myIP,
		wsPort:    wsPort,
		tokenMgr:  tokenMgr,
		peers:     make(map[string]*PeerInfo),
		eventChan: make(chan PeerEvent, 64),
	}
}

// SetCallbacks 设置事件回调
