	addr := &net.UDPAddr{
		IP:   net.IPv4zero,
		Port: broadcastPort,
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		return err
	}
	d.conn = conn
	d.running.Store(true)

	// 启动时立即发一次广播
	d.broadcastHeartbeat()

	// 启动事件转发 goroutine
	go d.eventForwarder()

	// 启动广播 goroutine
	go d.broadcastLoop()

	// 启动监听 goroutine
	go d.listenLoop()

	return nil
}

// Stop 停止发现服务
func (d *Discovery) Stop() {
	d.running.Store(false)

	// 发送 goodbye 广播
	interfaces := getBroadcastInterfaces()
	goodbye, _ := json.Marshal(map[string]string{
		"type": "goodbye",
		"uuid": d.myUUID,
	})
	for _, iface := range interfaces {
		addr := &net.UDPAddr{IP: net.ParseIP(iface.BroadcastAddr), Port: broadcastPort}
		d.conn.WriteToUDP(goodbye, addr)
	}

	if d.conn != nil {
		d.conn.Close()
	}
