package main

import (
	"encoding/json"
	"net/http"
	"path/filepath"
	"strings"
)

// ============================================================
// REST API 处理器
// ============================================================

// registerHandlers 注册所有 REST API 路由
func (app *AppState) registerHandlers(mux *http.ServeMux) {
	mux.HandleFunc("GET /api/me", app.handleMe)
	mux.HandleFunc("GET /api/peers", app.handlePeers)
	mux.HandleFunc("GET /api/contacts", app.handleContacts)
	mux.HandleFunc("GET /api/messages/{uuid}", app.handleMessages)
	mux.HandleFunc("POST /api/config", app.handleUpdateConfig)
	mux.HandleFunc("DELETE /api/contacts/{uuid}", app.handleDeleteContact)
	mux.HandleFunc("GET /api/pending", app.handlePending)
	mux.HandleFunc("GET /api/downloads/{file...}", app.handleDownload)
}

// handleMe 返回本机信息
func (app *AppState) handleMe(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, map[string]any{
		"uuid":    app.MyUUID,
		"name":    app.MyName,
		"ip":      app.MyIP,
		"network": app.Network,
		"ws_port": app.WSPort,
		"token":   app.TokenMgr.GetToken(),
	})
}

// handlePeers 返回当前在线节点列表
func (app *AppState) handlePeers(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, app.Discovery.GetPeers())
}

// handleContacts 返回历史联系人列表，合并在线状态
func (app *AppState) handleContacts(w http.ResponseWriter, r *http.Request) {
	contacts := app.Storage.ListContacts()
	onlinePeers := make(map[string]bool)
	for _, p := range app.Discovery.GetPeers() {
		onlinePeers[p.UUID] = true
	}

	type contactWithStatus struct {
		ContactSummary
		Status string `json:"status"`
	}

	result := make([]contactWithStatus, 0, len(contacts))
	for _, c := range contacts {
		status := "offline"
		if onlinePeers[c.UUID] {
			status = "online"
		}
		result = append(result, contactWithStatus{
			ContactSummary: c,
			Status:         status,
		})
	}

	writeJSON(w, result)
}

// handleMessages 返回指定联系人的聊天记录
func (app *AppState) handleMessages(w http.ResponseWriter, r *http.Request) {
	uuid := r.PathValue("uuid")
	messages := app.Storage.GetMessages(uuid)
	if messages == nil {
		messages = []Message{}
	}
	writeJSON(w, messages)
}

// handleUpdateConfig 修改本机昵称
func (app *AppState) handleUpdateConfig(w http.ResponseWriter, r *http.Request) {
	var data map[string]any
	if err := json.NewDecoder(r.Body).Decode(&data); err != nil {
		http.Error(w, "无效的 JSON", http.StatusBadRequest)
		return
	}

	newName, _ := data["name"].(string)
	newName = strings.TrimSpace(newName)
	if newName == "" {
		http.Error(w, "名称不能为空", http.StatusBadRequest)
		return
	}

	app.mu.Lock()
	app.MyName = newName
	app.Discovery.myName = newName
	app.mu.Unlock()

	config := app.Storage.LoadConfig()
	config["name"] = newName
	app.Storage.SaveConfig(config)

	writeJSON(w, map[string]string{"status": "ok", "name": newName})
}

// handleDeleteContact 删除联系人及聊天记录
func (app *AppState) handleDeleteContact(w http.ResponseWriter, r *http.Request) {
	uuid := r.PathValue("uuid")

	// 1. 通知对端标记我们为不可信
	app.activeChatsMu.Lock()
	peerWS := app.ActiveChats[uuid]
	app.activeChatsMu.Unlock()

	if peerWS != nil {
		safeSendJSON(peerWS, map[string]any{
			"type": "contact_untrusted",
			"uuid": app.MyUUID,
			"name": app.MyName,
		})
	}

	// 2. 关闭与对端的活跃聊天连接
	app.activeChatsMu.Lock()
	peerWS = app.ActiveChats[uuid]
	delete(app.ActiveChats, uuid)
	app.activeChatsMu.Unlock()

	if peerWS != nil {
		peerWS.Close()
	}

	// 3. 清理待确认的连接请求
	app.pendingMu.Lock()
	delete(app.PendingConns, uuid)
	app.pendingMu.Unlock()

	// 4. 清理进行中的文件传输
	app.transfersMu.Lock()
	for tid, t := range app.Transfers {
		if t.FromUUID == uuid || t.ToUUID == uuid {
			delete(app.Transfers, tid)
			app.Storage.DeleteProgress(tid)
		}
	}
	app.transfersMu.Unlock()

	// 5. 删除联系人及聊天记录
	app.Storage.DeleteContact(uuid)

	// 6. 通知浏览器
	app.notifyBrowser(map[string]any{
		"type": "contact_deleted",
		"uuid": uuid,
	})

	writeJSON(w, map[string]string{"status": "ok"})
}

// handlePending 返回待处理的连接请求列表
func (app *AppState) handlePending(w http.ResponseWriter, r *http.Request) {
	app.pendingMu.Lock()
