package main

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// ============================================================
// 文件传输数据结构
// ============================================================

// TransferInfo 传输元信息
type TransferInfo struct {
	TransferID     string `json:"transfer_id"`
	FileName       string `json:"file_name"`
	FileSize       int64  `json:"file_size"`
	TotalChunks    int    `json:"total_chunks"`
	ChunkSize      int    `json:"chunk_size"`
	FromUUID       string `json:"from_uuid"`
	FromName       string `json:"from_name"`
	ToUUID         string `json:"to_uuid"`
	ReceivedChunks []int  `json:"received_chunks"`
	ReceivedBytes  int64  `json:"received_bytes"`
	Status         string `json:"status"` // "pending" | "receiving" | "rejected"
	CreatedAt      string `json:"created_at"`
}

// ============================================================
// 文件传输 HTTP API 处理器注册
// ============================================================

func (app *AppState) registerTransferHandlers(mux *http.ServeMux) {
	mux.HandleFunc("POST /api/transfer/request", app.handleTransferRequest)
	mux.HandleFunc("POST /api/transfer/chunk", app.handleTransferChunk)
	mux.HandleFunc("POST /api/transfer/complete", app.handleTransferComplete)
	mux.HandleFunc("GET /api/transfer/status/{transfer_id}", app.handleTransferStatus)
}

// ============================================================
// 文件传输 API 处理
// ============================================================

// handleTransferRequest 接收来自其他后端的文件传输请求
func (app *AppState) handleTransferRequest(w http.ResponseWriter, r *http.Request) {
	var data map[string]any
	if err := json.NewDecoder(r.Body).Decode(&data); err != nil {
		http.Error(w, "无效的 JSON", http.StatusBadRequest)
		return
	}

	transferID, _ := data["transfer_id"].(string)
	fileName, _ := data["file_name"].(string)
	fromUUID, _ := data["from_uuid"].(string)
	fromName, _ := data["from_name"].(string)
	fromToken, _ := data["token"].(string)
	resume, _ := data["resume"].(bool)

	// 路径穿越防护：只取文件名部分
	fileName = filepath.Base(fileName)

	if transferID == "" || fromUUID == "" {
		http.Error(w, "缺少必要参数", http.StatusBadRequest)
		return
	}

	// Token 验证
	if !app.Discovery.VerifyToken(fromUUID, fromToken) {
		peer := app.Discovery.GetPeer(fromUUID)
		peerIP := ""
		peerWSPort := 50002
		if peer != nil {
			peerIP = peer.IP
			peerWSPort = peer.WSPort
		}
		if peerIP == "" || !app.verifyTokenViaAPI(fromUUID, fromToken, peerIP, peerWSPort) {
			http.Error(w, "token 验证失败", http.StatusForbidden)
			return
		}
	}

	// 解析文件参数
	fileSize := int64(0)
	if v, ok := data["file_size"].(float64); ok {
		fileSize = int64(v)
	}
	totalChunks := 0
	if v, ok := data["total_chunks"].(float64); ok {
		totalChunks = int(v)
	}
	chunkSize := 65536
	if v, ok := data["chunk_size"].(float64); ok {
		chunkSize = int(v)
	}

	// 续传：已有进度文件则自动进入接收状态
	existingProgress := app.Storage.LoadProgress(transferID)
	status := "pending"
	if resume && existingProgress != nil {
		status = "receiving"
	}

	// 保留旧传输中已收到的分片数据
	app.transfersMu.Lock()
	oldTransfer := app.Transfers[transferID]
	var oldReceivedChunks []int
	var oldReceivedBytes int64
	if oldTransfer != nil {
		oldReceivedChunks = oldTransfer.ReceivedChunks
		oldReceivedBytes = oldTransfer.ReceivedBytes
	}

	app.Transfers[transferID] = &TransferInfo{
		TransferID:     transferID,
		FileName:       fileName,
		FileSize:       fileSize,
		TotalChunks:    totalChunks,
		ChunkSize:      chunkSize,
		FromUUID:       fromUUID,
		FromName:       fromName,
		ReceivedChunks: oldReceivedChunks,
		ReceivedBytes:  oldReceivedBytes,
		Status:         status,
		CreatedAt:      time.Now().Format(time.RFC3339),
	}
	app.transfersMu.Unlock()

	// 通知浏览器
	app.notifyBrowser(map[string]any{
		"type":          "incoming_file_request",
		"transfer_id":   transferID,
		"file_name":     fileName,
		"file_size":     fileSize,
		"from_uuid":     fromUUID,
		"from_name":     fromName,
		"resume":        resume || status == "receiving",
	})

	writeJSON(w, map[string]string{"status": "ok"})
}

// handleTransferChunk 接收文件分片（Base64 编码）
func (app *AppState) handleTransferChunk(w http.ResponseWriter, r *http.Request) {
	var data map[string]any
	if err := json.NewDecoder(r.Body).Decode(&data); err != nil {
		http.Error(w, "无效的 JSON", http.StatusBadRequest)
		return
	}

	transferID, _ := data["transfer_id"].(string)
	chunkDataB64, _ := data["data"].(string)

	chunkIndex := 0
	if v, ok := data["chunk_index"].(float64); ok {
		chunkIndex = int(v)
	}

	app.transfersMu.Lock()
	t, ok := app.Transfers[transferID]
	app.transfersMu.Unlock()

	if !ok {
		http.Error(w, "传输不存在", http.StatusNotFound)
		return
	}
	if t.Status != "receiving" {
		http.Error(w, "传输状态异常: "+t.Status, http.StatusBadRequest)
		return
	}

	// Base64 解码
	chunkData, err := base64.StdEncoding.DecodeString(chunkDataB64)
	if err != nil {
		http.Error(w, "无效的 Base64 数据", http.StatusBadRequest)
		return
	}

	// 获取或创建传输锁
	lock := app.getTransferLock(transferID)
	lock.Lock()
	defer lock.Unlock()

	// 写入 .part 文件（使用 WriteAt 而非追加模式，保证续传时数据正确）
	partPath := filepath.Join(app.Storage.downloadsDir, t.FileName+".part")
	f, err := os.OpenFile(partPath, os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		http.Error(w, "无法创建文件", http.StatusInternalServerError)
		return
	}
	defer f.Close()

	f.WriteAt(chunkData, int64(chunkIndex*t.ChunkSize))

	// 去重计数
	if !containsInt(t.ReceivedChunks, chunkIndex) {
		t.ReceivedChunks = append(t.ReceivedChunks, chunkIndex)
		t.ReceivedBytes += int64(len(chunkData))
	}

	// 持久化进度
	app.Storage.SaveProgress(transferID, &ProgressInfo{
		FileName:       t.FileName,
		FileSize:       t.FileSize,
		ChunkSize:      t.ChunkSize,
		ReceivedChunks: t.ReceivedChunks,
		ReceivedBytes:  t.ReceivedBytes,
		TotalChunks:    t.TotalChunks,
		FromUUID:       t.FromUUID,
		FromName:       t.FromName,
		Status:         "receiving",
		CreatedAt:      t.CreatedAt,
		LastUpdate:     time.Now().Format(time.RFC3339),
	})

	// 通知浏览器进度
	app.notifyBrowser(map[string]any{
		"type":           "transfer_progress",
		"transfer_id":    transferID,
		"file_name":      t.FileName,
		"received_bytes": t.ReceivedBytes,
		"total_bytes":    t.FileSize,
	})

	writeJSON(w, map[string]any{
		"status":         "ok",
		"chunk_index":    chunkIndex,
		"received_bytes": t.ReceivedBytes,
	})
}

// handleTransferComplete 文件传输完成：校验并重命名为最终文件
func (app *AppState) handleTransferComplete(w http.ResponseWriter, r *http.Request) {
	var data map[string]any
	if err := json.NewDecoder(r.Body).Decode(&data); err != nil {
		http.Error(w, "无效的 JSON", http.StatusBadRequest)
		return
	}

	transferID, _ := data["transfer_id"].(string)

	app.transfersMu.Lock()
	t, ok := app.Transfers[transferID]
	app.transfersMu.Unlock()

	if !ok {
		http.Error(w, "传输不存在", http.StatusNotFound)
		return
	}

	partPath := filepath.Join(app.Storage.downloadsDir, t.FileName+".part")
	finalPath, _ := app.Storage.GetDownloadPath(t.FileName)

	verified := false
	if info, err := os.Stat(partPath); err == nil {
		if info.Size() == t.FileSize {
			os.Rename(partPath, finalPath)
			verified = true
		}
	}

	app.Storage.DeleteProgress(transferID)
	app.transfersMu.Lock()
	delete(app.Transfers, transferID)
	app.transfersMu.Unlock()

	app.notifyBrowser(map[string]any{
		"type":        "transfer_complete",
		"transfer_id": transferID,
		"file_name":   t.FileName,
		"verified":    verified,
	})

	writeJSON(w, map[string]any{
		"status":   "ok",
		"verified": verified,
	})
}

// handleTransferStatus 查询传输进度（用于断点续传）
func (app *AppState) handleTransferStatus(w http.ResponseWriter, r *http.Request) {
	transferID := r.PathValue("transfer_id")

	// 先查内存
	app.transfersMu.Lock()
	t, ok := app.Transfers[transferID]
	app.transfersMu.Unlock()

	if ok {
		writeJSON(w, map[string]any{
			"transfer_id":           transferID,
			"file_name":             t.FileName,
			"file_size":             t.FileSize,
			"received_bytes":        t.ReceivedBytes,
			"received_chunks_count": len(t.ReceivedChunks),
			"total_chunks":          t.TotalChunks,
			"status":                t.Status,
		})
		return
	}

	// 再查持久化进度文件
	progress := app.Storage.LoadProgress(transferID)
	if progress != nil {
		writeJSON(w, map[string]any{
			"transfer_id":           transferID,
			"file_name":             progress.FileName,
			"file_size":             progress.FileSize,
			"received_bytes":        progress.ReceivedBytes,
			"received_chunks_count": len(progress.ReceivedChunks),
			"total_chunks":          progress.TotalChunks,
			"status":                progress.Status,
		})
		return
	}

	http.Error(w, "传输不存在", http.StatusNotFound)
}

// ============================================================
// 工具函数
// ============================================================

// getTransferLock 获取或创建传输专用锁
func (app *AppState) getTransferLock(transferID string) *sync.Mutex {
	app.transfersMu.Lock()
	defer app.transfersMu.Unlock()

	if lock, ok := app.TransferLocks[transferID]; ok {
		return lock
	}
	lock := &sync.Mutex{}
	app.TransferLocks[transferID] = lock
	return lock
}

// containsInt 检查切片中是否包含指定整数
func containsInt(slice []int, val int) bool {
	for _, v := range slice {
		if v == val {
			return true
		}
	}
	return false
}

