package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"path/filepath"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// ============================================================
// WebSocket Upgrader
// ============================================================

var wsUpgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

// ============================================================
// PendingInfo 待确认的连接请求
// ============================================================

// PendingInfo 待确认的连接信息
type PendingInfo struct {
	Conn      *websocket.Conn
	Name      string
	UUID      string
	ConfirmCh chan bool // true = 接受, false = 拒绝
	Accepted  bool
}

// ============================================================
// AppState WebSocket 核心
// ============================================================

// registerWSHandlers 注册 WebSocket 路由
func (app *AppState) registerWSHandlers(mux *http.ServeMux) {
	mux.HandleFunc("GET /ws/control", app.handleControlWS)
	mux.HandleFunc("GET /ws/chat", app.handleChatWS)
}

// ============================================================
// /ws/control — 控制通道（浏览器 ↔ 自己后端）
// ============================================================

func (app *AppState) handleControlWS(w http.ResponseWriter, r *http.Request) {
	conn, err := wsUpgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	app.mu.Lock()
	app.ControlWS = conn
	app.mu.Unlock()

	defer func() {
		app.mu.Lock()
		app.ControlWS = nil
		app.mu.Unlock()
	}()

	// 发送初始化配置
	app.sendInit(conn)

	// 消息循环
	for {
		var msg map[string]any
		if err := conn.ReadJSON(&msg); err != nil {
			break
		}
		app.handleControlMessage(conn, msg)
	}
}

// sendInit 发送初始化配置给浏览器
func (app *AppState) sendInit(conn *websocket.Conn) {
	allContacts := app.Storage.ListContacts()
	onlinePeersList := app.Discovery.GetPeers()

	// 过滤自己
	onlinePeersFiltered := make([]PeerInfo, 0)
	onlinePeerIDs := make(map[string]bool)
	for _, p := range onlinePeersList {
		if p.UUID != app.MyUUID {
			onlinePeersFiltered = append(onlinePeersFiltered, p)
			onlinePeerIDs[p.UUID] = true
		}
	}

	type initContact struct {
		ContactSummary
		Status string `json:"status"`
	}
	initContacts := make([]initContact, 0)
	for _, c := range allContacts {
		if c.UUID == app.MyUUID {
			continue
		}
		status := "offline"
		if onlinePeerIDs[c.UUID] {
			status = "online"
		}
		initContacts = append(initContacts, initContact{
			ContactSummary: c,
			Status:         status,
		})
	}

	// active_peers 列表
	app.activeChatsMu.Lock()
	activePeers := make([]string, 0, len(app.ActiveChats))
	for uuid := range app.ActiveChats {
		activePeers = append(activePeers, uuid)
	}
	app.activeChatsMu.Unlock()

	safeSendJSON(conn, map[string]any{
		"type":         "init",
		"uuid":         app.MyUUID,
		"name":         app.MyName,
		"ip":           app.MyIP,
		"network":      app.Network,
		"ws_port":      app.WSPort,
		"token":        app.TokenMgr.GetToken(),
		"contacts":     initContacts,
		"online_peers": onlinePeersFiltered,
		"active_peers": activePeers,
	})
}

// handleControlMessage 处理控制 WS 消息
func (app *AppState) handleControlMessage(conn *websocket.Conn, msg map[string]any) {
	msgType, _ := msg["type"].(string)

	switch msgType {
	case "update_name":
		newName, _ := msg["name"].(string)
		if newName != "" {
			app.mu.Lock()
			app.MyName = newName
			app.Discovery.myName = newName
			app.mu.Unlock()

			config := app.Storage.LoadConfig()
			config["name"] = newName
			app.Storage.SaveConfig(config)

			safeSendJSON(conn, map[string]any{
				"type": "name_updated",
				"name": newName,
			})
		}

	case "connection_response":
		app.handleConnectionResponse(msg)

	case "file_response":
		app.handleFileResponse(msg)

	case "file_cancel":
		app.handleFileCancel(msg)

	case "disconnect":
		app.handleDisconnectFromBrowser(msg)

	case "register_transfer":
		transferID, _ := msg["transfer_id"].(string)
		if transferID != "" {
			fileName, _ := msg["file_name"].(string)
			fileSize := int64(0)
			if v, ok := msg["file_size"].(float64); ok {
				fileSize = int64(v)
			}
			totalChunks := 0
			if v, ok := msg["total_chunks"].(float64); ok {
				totalChunks = int(v)
			}
			chunkSize := 65536
			if v, ok := msg["chunk_size"].(float64); ok {
				chunkSize = int(v)
			}
			fromUUID, _ := msg["from_uuid"].(string)
			fromName, _ := msg["from_name"].(string)

			app.transfersMu.Lock()
			app.Transfers[transferID] = &TransferInfo{
				TransferID:  transferID,
				FileName:    fileName,
				FileSize:    fileSize,
				TotalChunks: totalChunks,
				ChunkSize:   chunkSize,
				FromUUID:    fromUUID,
				FromName:    fromName,
				Status:      "pending",
				CreatedAt:   time.Now().Format(time.RFC3339),
			}
			app.transfersMu.Unlock()
		}

	case "chat_message":
		app.handleChatMessageFromBrowser(msg)

	case "file_request":
		app.handleFileRequestFromBrowser(msg)

	case "save_message":
		app.handleSaveMessage(msg)

	case "save_contact":
		uuid, _ := msg["uuid"].(string)
		name, _ := msg["name"].(string)
		ip, _ := msg["ip"].(string)
		wsPort := 50002
		if v, ok := msg["ws_port"].(float64); ok {
			wsPort = int(v)
		}
		if uuid != "" {
			app.Storage.UpsertContact(uuid, name, ip, wsPort)
		}

	case "mark_untrusted":
		uuid, _ := msg["uuid"].(string)
		if uuid != "" {
			app.Storage.MarkContactUntrusted(uuid)
			app.notifyBrowser(map[string]any{
				"type": "contact_untrusted",
				"uuid": uuid,
			})
		}

	case "delete_contact":
		app.handleDeleteContactFromBrowser(msg)
	}
}

// ============================================================
// 控制消息处理函数
// ============================================================

func (app *AppState) handleConnectionResponse(msg map[string]any) {
	targetUUID, _ := msg["to_uuid"].(string)
	accepted, _ := msg["accepted"].(bool)

	app.pendingMu.Lock()
	pendingInfo, ok := app.PendingConns[targetUUID]
	app.pendingMu.Unlock()

	if !ok || pendingInfo == nil {
		return
	}

	if accepted {
		pendingInfo.Accepted = true
		pendingInfo.ConfirmCh <- true

		safeSendJSON(pendingInfo.Conn, map[string]any{
			"type":    "connect_accepted",
			"uuid":    app.MyUUID,
			"name":    app.MyName,
			"ip":      app.MyIP,
			"ws_port": app.WSPort,
		})
	} else {
		safeSendJSON(pendingInfo.Conn, map[string]any{
			"type": "connect_rejected",
		})
		pendingInfo.Conn.Close()
		pendingInfo.ConfirmCh <- false
	}
}

func (app *AppState) handleFileResponse(msg map[string]any) {
	transferID, _ := msg["transfer_id"].(string)
	accepted, _ := msg["accepted"].(bool)

	app.transfersMu.Lock()
	t, ok := app.Transfers[transferID]
	app.transfersMu.Unlock()

	if !ok || t == nil {
		return
	}

	app.activeChatsMu.Lock()
	peerWS := app.ActiveChats[t.FromUUID]
	app.activeChatsMu.Unlock()

	if accepted {
		t.Status = "receiving"
		if peerWS != nil {
			safeSendJSON(peerWS, map[string]any{
				"type":        "file_response",
				"transfer_id": transferID,
				"accepted":    true,
			})
		} else {
			app.notifyBrowser(map[string]any{
				"type":        "forward_file_response",
				"transfer_id": transferID,
				"accepted":    true,
				"to_uuid":     t.FromUUID,
			})
		}
	} else {
		t.Status = "rejected"
		app.Storage.DeleteProgress(transferID)
		app.transfersMu.Lock()
		delete(app.Transfers, transferID)
		app.transfersMu.Unlock()

		if peerWS != nil {
			safeSendJSON(peerWS, map[string]any{
				"type":        "file_response",
				"transfer_id": transferID,
				"accepted":    false,
			})
		} else {
			app.notifyBrowser(map[string]any{
				"type":        "forward_file_response",
				"transfer_id": transferID,
				"accepted":    false,
				"to_uuid":     t.FromUUID,
			})
		}
	}
}

func (app *AppState) handleFileCancel(msg map[string]any) {
	transferID, _ := msg["transfer_id"].(string)

	app.transfersMu.Lock()
	t, ok := app.Transfers[transferID]
	delete(app.Transfers, transferID)
	app.transfersMu.Unlock()

	if ok && t != nil {
		app.Storage.DeleteProgress(transferID)
		app.activeChatsMu.Lock()
		peerWS := app.ActiveChats[t.FromUUID]
		app.activeChatsMu.Unlock()

		safeSendJSON(peerWS, map[string]any{
			"type":        "file_cancel",
			"transfer_id": transferID,
		})
	}
}

func (app *AppState) handleDisconnectFromBrowser(msg map[string]any) {
	targetUUID, _ := msg["to_uuid"].(string)
	if targetUUID == "" {
		return
	}

	app.activeChatsMu.Lock()
	peerWS := app.ActiveChats[targetUUID]
	delete(app.ActiveChats, targetUUID)
	app.activeChatsMu.Unlock()

	if peerWS != nil {
		peerWS.Close()
	}

	app.notifyBrowser(map[string]any{
		"type": "disconnected",
		"uuid": targetUUID,
	})
}

func (app *AppState) handleChatMessageFromBrowser(msg map[string]any) {
	targetUUID, _ := msg["to_uuid"].(string)
	msgID, _ := msg["msg_id"].(string)
	content, _ := msg["content"].(string)

	app.activeChatsMu.Lock()
	peerWS := app.ActiveChats[targetUUID]
	app.activeChatsMu.Unlock()

	if peerWS == nil {
		app.notifyBrowser(map[string]any{
			"type":   "send_failed",
			"msg_id": msgID,
			"reason": "not_connected",
		})
		return
	}

	err := peerWS.WriteJSON(map[string]any{
		"type":      "chat",
		"msg_id":    msgID,
		"from":      app.MyUUID,
		"from_name": app.MyName,
		"content":   content,
		"timestamp": time.Now().Format(time.RFC3339),
	})

	if err != nil {
		app.notifyBrowser(map[string]any{
			"type":   "send_failed",
			"msg_id": msgID,
			"reason": "send_error",
		})
		return
	}

	// 保存自己发的消息
	app.Storage.AppendMessage(targetUUID, "me", content, msgID, "chat", nil)
}

func (app *AppState) handleFileRequestFromBrowser(msg map[string]any) {
	targetUUID, _ := msg["to_uuid"].(string)
	transferID, _ := msg["transfer_id"].(string)
	fileName, _ := msg["file_name"].(string)
	fileSize := int64(0)
	if v, ok := msg["file_size"].(float64); ok {
		fileSize = int64(v)
	}
	chunkSize := 65536
	if v, ok := msg["chunk_size"].(float64); ok {
		chunkSize = int(v)
	}
	totalChunks := 0
	if v, ok := msg["total_chunks"].(float64); ok {
		totalChunks = int(v)
	}
	resume, _ := msg["resume"].(bool)

	// 查找对端 IP 和端口
	peer := app.Discovery.GetPeer(targetUUID)
	if peer == nil {
		// 查历史联系人
		for _, c := range app.Storage.ListContacts() {
			if c.UUID == targetUUID {
				peer = &PeerInfo{IP: c.IP, WSPort: c.WSPort}
				break
			}
		}
	}

	if peer == nil || peer.IP == "" {
		app.notifyBrowser(map[string]any{
			"type":        "file_request_response",
			"transfer_id": transferID,
			"accepted":    false,
		})
		return
	}

	// 优先：HTTP POST 到对端后端
	relayed := false
	reqURL := fmt.Sprintf("http://%s:%d/api/transfer/request", peer.IP, peer.WSPort)
	reqBody, _ := json.Marshal(map[string]any{
		"transfer_id":  transferID,
		"file_name":    filepath.Base(fileName),
		"file_size":    fileSize,
		"chunk_size":   chunkSize,
		"total_chunks": totalChunks,
		"from_uuid":    app.MyUUID,
		"from_name":    app.MyName,
		"token":        app.TokenMgr.GetToken(),
		"resume":       resume,
	})

	resp, err := httpPostJSON(reqURL, reqBody)
	if err == nil {
		resp.Body.Close()
		relayed = true
	}

	// 回退：通过 chat WS 发送
	if !relayed {
		app.activeChatsMu.Lock()
		peerWS := app.ActiveChats[targetUUID]
		app.activeChatsMu.Unlock()

		if peerWS != nil {
			safeSendJSON(peerWS, map[string]any{
				"type":         "file_request",
				"transfer_id":  transferID,
				"file_name":    msg["file_name"],
				"file_size":    fileSize,
				"chunk_size":   chunkSize,
				"total_chunks": totalChunks,
				"resume":       resume,
			})
		} else {
			app.notifyBrowser(map[string]any{
				"type":        "file_request_response",
				"transfer_id": transferID,
				"accepted":    false,
			})
		}
	}
}

func (app *AppState) handleSaveMessage(msg map[string]any) {
	peerUUID, _ := msg["peer_uuid"].(string)
	sender, _ := msg["sender"].(string)
	content, _ := msg["content"].(string)
	msgID, _ := msg["msg_id"].(string)
	msgType, _ := msg["msg_type"].(string)
	if msgType == "" {
		msgType = "chat"
	}

	if peerUUID == "" || msgID == "" {
		return
	}

	extra := make(map[string]any)
	if msgType == "file" {
		for _, key := range []string{"file_name", "file_size", "transfer_id", "status", "progress"} {
			if v, ok := msg[key]; ok {
				extra[key] = v
			}
		}
	}

	app.Storage.AppendMessage(peerUUID, sender, content, msgID, msgType, extra)
}

func (app *AppState) handleDeleteContactFromBrowser(msg map[string]any) {
	uuid, _ := msg["uuid"].(string)
	if uuid == "" {
		return
	}

	// 通知对端
	app.activeChatsMu.Lock()
	peerWS := app.ActiveChats[uuid]
	app.activeChatsMu.Unlock()

	if peerWS != nil {
		safeSendJSON(peerWS, map[string]any{
			"type": "contact_untrusted",
			"uuid": app.MyUUID,
			"name": app.MyName,
		})
	}

	// 关闭 WS
	app.activeChatsMu.Lock()
	peerWS = app.ActiveChats[uuid]
	delete(app.ActiveChats, uuid)
	app.activeChatsMu.Unlock()

	if peerWS != nil {
		peerWS.Close()
	}

	// 清理
	app.pendingMu.Lock()
	delete(app.PendingConns, uuid)
	app.pendingMu.Unlock()

	app.transfersMu.Lock()
	for tid, t := range app.Transfers {
		if t.FromUUID == uuid || t.ToUUID == uuid {
			delete(app.Transfers, tid)
			app.Storage.DeleteProgress(tid)
		}
	}
	app.transfersMu.Unlock()

	app.Storage.DeleteContact(uuid)

	app.notifyBrowser(map[string]any{
		"type": "contact_deleted",
		"uuid": uuid,
	})
}

// ============================================================
// /ws/chat — 聊天通道（其他用户浏览器 → 自己后端）
// ============================================================

func (app *AppState) handleChatWS(w http.ResponseWriter, r *http.Request) {
	conn, err := wsUpgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	peerUUID := ""
	peerName := "Unknown"
	idleClosed := false

	defer func() {
		app.pendingMu.Lock()
		delete(app.PendingConns, peerUUID)
		app.pendingMu.Unlock()

		app.activeChatsMu.Lock()
		delete(app.ActiveChats, peerUUID)
		app.activeChatsMu.Unlock()

		if peerUUID != "" && !idleClosed {
			app.notifyBrowser(map[string]any{
				"type": "peer_disconnected",
				"uuid": peerUUID,
				"name": peerName,
			})
		}
		app.notifyPendingUpdate()
	}()

	// ===== 阶段1：连接请求与 Token 验证 =====
	var firstMsg map[string]any
	if err := conn.ReadJSON(&firstMsg); err != nil {
		return
	}

	msgType, _ := firstMsg["type"].(string)
	if msgType != "connect_request" {
		safeSendJSON(conn, map[string]any{
			"type":   "connect_rejected",
			"reason": "expected connect_request",
		})
		return
	}

	peerUUID, _ = firstMsg["uuid"].(string)
	peerName, _ = firstMsg["name"].(string)
	peerToken, _ := firstMsg["token"].(string)

	// 防止自连
	if peerUUID == app.MyUUID {
		safeSendJSON(conn, map[string]any{
			"type":   "connect_rejected",
			"reason": "self_connect",
		})
		return
	}

	// 获取客户端 IP
	peerIP, _ := firstMsg["ip"].(string)
	if peerIP == "" {
		peerIP = getClientIP(r)
	}
	peerWSPort := 50002
	if v, ok := firstMsg["ws_port"].(float64); ok {
		peerWSPort = int(v)
	}

	// Token 验证
	if !app.Discovery.VerifyToken(peerUUID, peerToken) {
		if !app.verifyTokenViaAPI(peerUUID, peerToken, peerIP, peerWSPort) {
			safeSendJSON(conn, map[string]any{
				"type":   "connect_rejected",
				"reason": "invalid_token",
			})
			return
		}
		// 跨子网验证通过：写入 peer_list
		app.Discovery.peersMu.Lock()
		app.Discovery.peers[peerUUID] = &PeerInfo{
			UUID:     peerUUID,
			Name:     peerName,
			IP:       peerIP,
			WSPort:   peerWSPort,
			Token:    peerToken,
			LastSeen: float64(time.Now().UnixMilli()) / 1000.0,
			Status:   "online",
		}
		app.Discovery.peersMu.Unlock()
	}

	// 获取对端信息
	peerInfo := app.Discovery.GetPeer(peerUUID)
	if peerInfo != nil && peerInfo.IP != "" {
		peerIP = peerInfo.IP
	}
	if peerInfo != nil && peerInfo.WSPort != 0 {
		peerWSPort = peerInfo.WSPort
	}

	// 判断是新连接还是重连
	existingContact := app.Storage.GetContact(peerUUID)
	acceptedResult := false

	if existingContact != nil && existingContact.Trusted {
		// 已知可信联系人：自动接受
		acceptedResult = true
		if existingContact.Name != "" {
			peerName = existingContact.Name
		}
		safeSendJSON(conn, map[string]any{
			"type":    "connect_accepted",
			"uuid":    app.MyUUID,
			"name":    app.MyName,
			"ip":      app.MyIP,
			"ws_port": app.WSPort,
		})
	} else {
		// 新连接或不受信 → 等待用户确认
		confirmCh := make(chan bool, 1)
		app.pendingMu.Lock()
		app.PendingConns[peerUUID] = &PendingInfo{
			Conn:      conn,
			Name:      peerName,
			UUID:      peerUUID,
			ConfirmCh: confirmCh,
		}
		app.pendingMu.Unlock()

		app.notifyBrowser(map[string]any{
			"type":     "incoming_connection",
			"uuid":     peerUUID,
			"name":     peerName,
			"ip":       peerIP,
			"ws_port":  peerWSPort,
		})
		app.notifyPendingUpdate()

		// 等待浏览器响应（60秒超时）
		select {
		case accepted := <-confirmCh:
			acceptedResult = accepted
		case <-time.After(60 * time.Second):
			// 超时：清理并拒绝
			app.pendingMu.Lock()
			delete(app.PendingConns, peerUUID)
			app.pendingMu.Unlock()

			app.notifyBrowser(map[string]any{
				"type": "connection_timeout",
				"uuid": peerUUID,
				"name": peerName,
			})
			app.notifyPendingUpdate()

			safeSendJSON(conn, map[string]any{
				"type":   "connect_rejected",
				"reason": "timeout",
			})
			return
		}

		app.pendingMu.Lock()
		delete(app.PendingConns, peerUUID)
		app.pendingMu.Unlock()

		if !acceptedResult {
			return
		}
	}

	// ===== 阶段2：正常消息收发 =====
	app.activeChatsMu.Lock()
	app.ActiveChats[peerUUID] = conn
	app.activeChatsMu.Unlock()

	app.Storage.UpsertContact(peerUUID, peerName, peerIP, peerWSPort)

	app.notifyBrowser(map[string]any{
		"type": "connection_established",
		"uuid": peerUUID,
		"name": peerName,
		"ip":   peerIP,
	})
	app.notifyPendingUpdate()

	// 消息循环
	for {
		// 10分钟空闲超时
		conn.SetReadDeadline(time.Now().Add(10 * time.Minute))

		var msg map[string]any
		if err := conn.ReadJSON(&msg); err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				// 检查是否有活跃的文件传输
				if app.hasActiveTransfer(peerUUID) {
					continue
				}

				app.notifyBrowser(map[string]any{
					"type": "connection_idle_close",
					"uuid": peerUUID,
					"name": peerName,
				})
				idleClosed = true
				safeSendJSON(conn, map[string]any{
					"type":   "connection_closing",
					"reason": "idle_timeout",
				})
			}
			break
		}

		app.relayFromPeer(conn, peerUUID, peerName, msg)
	}
}

// relayFromPeer 将对方 WebSocket 发来的消息转发给本地浏览器
func (app *AppState) relayFromPeer(conn *websocket.Conn, peerUUID, peerName string, msg map[string]any) {
	msgType, _ := msg["type"].(string)

	switch msgType {
	case "chat":
		msgID, _ := msg["msg_id"].(string)
		content, _ := msg["content"].(string)
		timestamp, _ := msg["timestamp"].(string)

		app.Storage.AppendMessage(peerUUID, peerUUID, content, msgID, "chat", nil)
		app.notifyBrowser(map[string]any{
			"type":      "chat_message",
			"from":      peerUUID,
			"from_name": peerName,
			"msg_id":    msgID,
			"content":   content,
			"timestamp": timestamp,
		})
		safeSendJSON(conn, map[string]any{
			"type":   "ack",
			"msg_id": msgID,
		})

	case "file_request":
		transferID, _ := msg["transfer_id"].(string)
		fileName, _ := msg["file_name"].(string)
		fileName = filepath.Base(fileName)
		fileSize := int64(0)
		if v, ok := msg["file_size"].(float64); ok {
			fileSize = int64(v)
		}
		totalChunks := 0
		if v, ok := msg["total_chunks"].(float64); ok {
			totalChunks = int(v)
		}
		chunkSize := 65536
		if v, ok := msg["chunk_size"].(float64); ok {
			chunkSize = int(v)
		}
		resume, _ := msg["resume"].(bool)

		existingProgress := app.Storage.LoadProgress(transferID)

		// 保留旧传输数据
		app.transfersMu.Lock()
		oldTransfer := app.Transfers[transferID]
		var oldReceivedChunks []int
		var oldReceivedBytes int64
		if oldTransfer != nil {
			oldReceivedChunks = oldTransfer.ReceivedChunks
			oldReceivedBytes = oldTransfer.ReceivedBytes
		}

		status := "pending"
		if resume && existingProgress != nil {
			status = "receiving"
		}

		app.Transfers[transferID] = &TransferInfo{
			TransferID:     transferID,
			FileName:       fileName,
			FileSize:       fileSize,
			TotalChunks:    totalChunks,
			ChunkSize:      chunkSize,
			FromUUID:       peerUUID,
			FromName:       peerName,
			ReceivedChunks: oldReceivedChunks,
			ReceivedBytes:  oldReceivedBytes,
			Status:         status,
			CreatedAt:      time.Now().Format(time.RFC3339),
		}
		app.transfersMu.Unlock()

		if resume && existingProgress != nil {
			safeSendJSON(conn, map[string]any{
				"type":        "file_response",
				"transfer_id": transferID,
				"accepted":    true,
			})
			app.notifyBrowser(map[string]any{
				"type":        "transfer_resumed",
				"transfer_id": transferID,
				"file_name":   fileName,
				"from_name":   peerName,
			})
		} else {
			app.notifyBrowser(map[string]any{
				"type":        "incoming_file_request",
				"transfer_id": transferID,
				"file_name":   fileName,
				"file_size":   fileSize,
				"from_uuid":   peerUUID,
				"from_name":   peerName,
				"resume":      resume,
			})
		}

	case "file_response":
		app.notifyBrowser(map[string]any{
			"type":        "file_request_response",
			"transfer_id": msg["transfer_id"],
			"accepted":    msg["accepted"],
		})

	case "file_cancel":
		transferID, _ := msg["transfer_id"].(string)
		app.transfersMu.Lock()
		delete(app.Transfers, transferID)
		app.transfersMu.Unlock()
		app.Storage.DeleteProgress(transferID)
		app.notifyBrowser(map[string]any{
			"type":        "transfer_cancelled",
			"transfer_id": transferID,
		})

	case "ack":
		app.notifyBrowser(map[string]any{
			"type":   "message_ack",
			"msg_id": msg["msg_id"],
		})
	}
}

// ============================================================
// 辅助函数
// ============================================================

// notifyBrowser 向自己浏览器发送控制消息
func (app *AppState) notifyBrowser(msg map[string]any) {
	app.mu.Lock()
	ws := app.ControlWS
	app.mu.Unlock()

	if ws != nil {
		ws.WriteJSON(msg)
	}
}

// notifyPendingUpdate 通知浏览器待处理连接请求数量变化
func (app *AppState) notifyPendingUpdate() {
	app.pendingMu.Lock()
	count := len(app.PendingConns)
	app.pendingMu.Unlock()

	app.notifyBrowser(map[string]any{
		"type":  "pending_update",
		"count": count,
	})
}

// hasActiveTransfer 检查是否有活跃的文件传输
func (app *AppState) hasActiveTransfer(peerUUID string) bool {
	app.transfersMu.Lock()
	defer app.transfersMu.Unlock()

	for _, t := range app.Transfers {
		if t.FromUUID == peerUUID && t.Status == "receiving" {
			return true
		}
	}
	return false
}

// safeSendJSON 安全发送 JSON 消息，忽略发送失败
func safeSendJSON(conn *websocket.Conn, msg any) {
	if conn != nil {
		conn.WriteJSON(msg)
	}
}

// getClientIP 从请求中提取客户端 IP
func getClientIP(r *http.Request) string {
	// 检查 X-Forwarded-For
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		return xff
	}
	// 从 RemoteAddr 提取
	host, _, err := netSplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// netSplitHostPort 分离 host:port
func netSplitHostPort(addr string) (string, string, error) {
	// 简单实现
	for i := len(addr) - 1; i >= 0; i-- {
		if addr[i] == ':' {
			return addr[:i], addr[i+1:], nil
		}
	}
	return addr, "", nil
}

// ============================================================
// HTTP 辅助
// ============================================================

// httpPostJSON 发送 HTTP POST JSON 请求
func httpPostJSON(urlStr string, body []byte) (*http.Response, error) {
	req, err := http.NewRequest("POST", urlStr, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Body = io.NopCloser(nil)

	// 手动设置 body 的 reader
	req.Body = io.NopCloser(nil)
	req.GetBody = func() (io.ReadCloser, error) {
		return io.NopCloser(nil), nil
	}
	req.ContentLength = int64(len(body))

	// 使用 bytes reader
	return http.DefaultClient.Do(req)
}

// verifyTokenViaAPI 跨子网 Token 验证
func (app *AppState) verifyTokenViaAPI(uuid, token, ip string, port int) bool {
	reqURL := fmt.Sprintf("http://%s:%d/api/me", ip, port)

	client := &http.Client{Timeout: 3 * time.Second}
	resp, err := client.Get(reqURL)
	if err != nil {
		return false
	}
	defer resp.Body.Close()

	var data map[string]any
	if err := json.NewDecoder(resp.Body).Decode(&data); err != nil {
		return false
	}

	dataUUID, _ := data["uuid"].(string)
	dataToken, _ := data["token"].(string)
	return dataUUID == uuid && dataToken == token
}

// probeSavedContacts 定期 HTTP 探活历史联系人（跨子网）
func (app *AppState) probeSavedContacts() {
	for _, c := range app.Storage.ListContacts() {
		if c.UUID == app.MyUUID {
			continue
		}

		// 已被 UDP 广播发现的跳过
		if app.Discovery.GetPeer(c.UUID) != nil {
			continue
		}

		reqURL := fmt.Sprintf("http://%s:%d/api/me", c.IP, c.WSPort)
		client := &http.Client{Timeout: 1500 * time.Millisecond}
		resp, err := client.Get(reqURL)
		if err != nil {
			continue
		}

		var data map[string]any
		json.NewDecoder(resp.Body).Decode(&data)
		resp.Body.Close()

		dataUUID, _ := data["uuid"].(string)
		if dataUUID != c.UUID {
			continue
		}

		dataName, _ := data["name"].(string)
		wsPort := 50002
		if v, ok := data["ws_port"].(float64); ok {
			wsPort = int(v)
		}
		dataToken, _ := data["token"].(string)

		// 更新 peer_list
		app.Discovery.peersMu.Lock()
		existing := app.Discovery.peers[c.UUID]
		app.Discovery.peers[c.UUID] = &PeerInfo{
			UUID:          c.UUID,
			Name:          dataName,
			IP:            c.IP,
			WSPort:        wsPort,
			Token:         dataToken,
			PreviousToken: func() string {
				if existing != nil {
					return existing.Token
				}
				return ""
			}(),
			LastSeen:  float64(time.Now().UnixMilli()) / 1000.0,
			MissCount: 0,
			Status:    "online",
		}
		isNewOrOffline := existing == nil || existing.Status != "online"
		peerCopy := *app.Discovery.peers[c.UUID]
		app.Discovery.peersMu.Unlock()

		if isNewOrOffline {
			app.notifyPeerOnline(&peerCopy)
		}
	}
}

// notifyPeerOnline discovery 回调：节点上线 → 通知浏览器
func (app *AppState) notifyPeerOnline(peer *PeerInfo) {
	// 只在历史联系人已存在时才更新 name/ip
	if app.Storage.GetContact(peer.UUID) != nil {
		app.Storage.UpsertContact(peer.UUID, peer.Name, peer.IP, peer.WSPort)
	}
	app.notifyBrowser(map[string]any{
		"type":    "peer_online",
		"uuid":    peer.UUID,
		"name":    peer.Name,
		"ip":      peer.IP,
		"ws_port": peer.WSPort,
		"token":   peer.Token,
	})
}

// notifyPeerOffline discovery 回调：节点下线 → 通知浏览器
func (app *AppState) notifyPeerOffline(peer *PeerInfo) {
	app.notifyBrowser(map[string]any{
		"type": "peer_offline",
		"uuid": peer.UUID,
		"name": peer.Name,
	})
}

