package main

import (
	"bytes"
	"context"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/gorilla/websocket"
)

// ============================================================
// MyInfo 本机信息
// ============================================================

// MyInfo 本机配置信息
type MyInfo struct {
	UUID    string `json:"uuid"`
	Name    string `json:"name"`
	IP      string `json:"ip"`
	Network string `json:"network"`
	WSPort  int    `json:"ws_port"`
}

// ============================================================
// AppState 全局应用状态
// ============================================================

// AppState 集中管理所有共享状态
type AppState struct {
	// 本机信息
	MyUUID  string
	MyName  string
	MyIP    string
	WSPort  int
	Network string

	// 子组件
	Storage   *Storage
	TokenMgr  *TokenManager
	Discovery *Discovery

	// WebSocket 连接
	mu         sync.Mutex
	ControlWS  *websocket.Conn

	activeChatsMu sync.Mutex
	ActiveChats   map[string]*websocket.Conn // uuid → WS

	pendingMu     sync.Mutex
	PendingConns  map[string]*PendingInfo // uuid → 待确认信息

	transfersMu   sync.Mutex
	Transfers     map[string]*TransferInfo   // transfer_id → 信息
	TransferLocks map[string]*sync.Mutex     // transfer_id → 每传输锁
}

// ============================================================
// main 入口
// ============================================================

func main() {
	// 1. 环境变量读取
	dataDir := os.Getenv("LANCHAT_DATA_DIR")
	if dataDir == "" {
		dataDir = "./data"
	}

	// 2. 初始化存储
	storage := NewStorage(dataDir)

	// 3. 加载/创建本机配置
	config := storage.LoadConfig()
	if config["uuid"] == nil || config["uuid"] == "" {
		config["uuid"] = generateUUID12()
		name, _ := os.Hostname()
		config["name"] = name
		storage.SaveConfig(config)
	}

	// 4. 获取本机 IP
	myIP := getLocalIP()

	// 5. 查找可用端口
	envPort := os.Getenv("LANCHAT_PORT")
	wsPort := findAvailablePort(50002, 10)
	if envPort != "" {
		fmt.Sscanf(envPort, "%d", &wsPort)
	}

	// 6. 组装 UUID（带端口后缀，同机多实例防冲突）
	baseUUID, _ := config["uuid"].(string)
	myUUID := baseUUID + "_" + fmt.Sprintf("%d", wsPort)
	myName, _ := config["name"].(string)
	if envName := os.Getenv("LANCHAT_NAME"); envName != "" {
		myName = envName
	}
	network := getNetworkSegment(myIP)

	fmt.Printf("[LanChat] 启动中...\n")
	fmt.Printf("  昵称: %s\n", myName)
	fmt.Printf("  网段: %s\n", network)
	fmt.Printf("  端口: %d\n", wsPort)
	fmt.Printf("  UUID: %s\n", myUUID)

	// 7. 清理过期进度文件
	storage.CleanupExpiredProgress(24)

	// 8. 初始化 Token 管理器
	tokenMgr := NewTokenManager()

	// 9. 初始化节点发现
	discovery := NewDiscovery(myUUID, myName, myIP, wsPort, tokenMgr)

	// 10. 创建 AppState
	app := &AppState{
		MyUUID:        myUUID,
		MyName:        myName,
		MyIP:          myIP,
		WSPort:        wsPort,
		Network:       network,
		Storage:       storage,
		TokenMgr:      tokenMgr,
		Discovery:     discovery,
		ActiveChats:   make(map[string]*websocket.Conn),
		PendingConns:  make(map[string]*PendingInfo),
		Transfers:     make(map[string]*TransferInfo),
		TransferLocks: make(map[string]*sync.Mutex),
	}

	// 11. 注册 discovery 回调
	discovery.SetCallbacks(app.notifyPeerOnline, app.notifyPeerOffline)

	// 12. 启动 discovery
	if err := discovery.Start(); err != nil {
		fmt.Printf("[LanChat] 启动发现服务失败: %v\n", err)
		fmt.Println("（可能端口被占用？程序将继续运行，但无法发现或被发现）")
	}

	// 13. 启动探活 goroutine
	go app.probeSavedContactsLoop()

	// 14. 设置路由
	mux := http.NewServeMux()

	// 静态文件
	staticDir := http.Dir("./static")
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServer(staticDir)))

	// 首页
	mux.HandleFunc("GET /", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		http.ServeFile(w, r, "./static/index.html")
	})

	// REST API
	app.registerHandlers(mux)

	// 文件传输 API
	app.registerTransferHandlers(mux)

	// WebSocket
	app.registerWSHandlers(mux)

	// CORS 中间件
	handler := corsMiddleware(mux)

	// 15. 启动 HTTP 服务器
	addr := fmt.Sprintf("0.0.0.0:%d", wsPort)
	server := &http.Server{
		Addr:         addr,
		Handler:      handler,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	// 优雅关闭
	go func() {
		sigChan := make(chan os.Signal, 1)
		signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
		<-sigChan
		fmt.Println("\n[LanChat] 正在关闭...")
		discovery.Stop()
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		server.Shutdown(ctx)
	}()

	fmt.Printf("[LanChat] 已启动: http://localhost:%d\n", wsPort)
