		fmt.Printf("[LanChat] 服务器错误: %v\n", err)
	}
	fmt.Println("[LanChat] 已停止")
}

// probeSavedContactsLoop 定期 HTTP 探活（每30秒）
func (app *AppState) probeSavedContactsLoop() {
	time.Sleep(3 * time.Second) // 等 UDP 广播先跑一轮
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		app.probeSavedContacts()
	}
}

