package main

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/gorilla/websocket"
)

// ============================================================
// MyInfo 本机信息
// ============================================================

// MyInfo 本机配置信息
type MyInfo struct {
	UUID    string `json:"uuid"`
	Name    string `json:"name"`
	IP      string `json:"ip"`
	Network string `json:"network"`
	WSPort  int    `json:"ws_port"`
}

// ============================================================
// AppState 全局应用状态
// ============================================================

// AppState 集中管理所有共享状态
type AppState struct {
	// 本机信息
	MyUUID  string
	MyName  string
	MyIP    string
	WSPort  int
	Network string

	// 子组件
	Storage   *Storage
	TokenMgr  *TokenManager
	Discovery *Discovery

	// WebSocket 连接
	mu         sync.Mutex
	ControlWS  *websocket.Conn

	activeChatsMu sync.Mutex
	ActiveChats   map[string]*websocket.Conn // uuid → WS

	pendingMu     sync.Mutex
	PendingConns  map[string]*PendingInfo // uuid → 待确认信息

	transfersMu   sync.Mutex
	Transfers     map[string]*TransferInfo   // transfer_id → 信息
	TransferLocks map[string]*sync.Mutex     // transfer_id → 每传输锁
}

// ============================================================
// main 入口
// ============================================================

func main() {
	// 1. 环境变量读取
	dataDir := os.Getenv("LANCHAT_DATA_DIR")
	if dataDir == "" {
		dataDir = "./data"
	}

	// 2. 初始化存储
	storage := NewStorage(dataDir)

	// 3. 加载/创建本机配置
	config := storage.LoadConfig()
	if config["uuid"] == nil || config["uuid"] == "" {
		config["uuid"] = generateUUID12()
		name, _ := os.Hostname()
		config["name"] = name
		storage.SaveConfig(config)
	}

	// 4. 获取本机 IP
	myIP := getLocalIP()

	// 5. 查找可用端口
	envPort := os.Getenv("LANCHAT_PORT")
	wsPort := findAvailablePort(50002, 10)
	if envPort != "" {
		fmt.Sscanf(envPort, "%d", &wsPort)
	}

	// 6. 组装 UUID（带端口后缀，同机多实例防冲突）
	baseUUID, _ := config["uuid"].(string)
	myUUID := baseUUID + "_" + fmt.Sprintf("%d", wsPort)
	myName, _ := config["name"].(string)
	if envName := os.Getenv("LANCHAT_NAME"); envName != "" {
		myName = envName
	}
	network := getNetworkSegment(myIP)

	fmt.Printf("[LanChat] 启动中...\n")
	fmt.Printf("  昵称: %s\n", myName)
	fmt.Printf("  网段: %s\n", network)
	fmt.Printf("  端口: %d\n", wsPort)
	fmt.Printf("  UUID: %s\n", myUUID)

	// 7. 清理过期进度文件
	storage.CleanupExpiredProgress(24)

	// 8. 初始化 Token 管理器
	tokenMgr := NewTokenManager()

	// 9. 初始化节点发现
	discovery := NewDiscovery(myUUID, myName, myIP, wsPort, tokenMgr)

	// 10. 创建 AppState
	app := &AppState{
		MyUUID:        myUUID,
		MyName:        myName,
		MyIP:          myIP,
		WSPort:        wsPort,
		Network:       network,
		Storage:       storage,
		TokenMgr:      tokenMgr,
		Discovery:     discovery,
		ActiveChats:   make(map[string]*websocket.Conn),
		PendingConns:  make(map[string]*PendingInfo),
		Transfers:     make(map[string]*TransferInfo),
		TransferLocks: make(map[string]*sync.Mutex),
	}

	// 11. 注册 discovery 回调
	discovery.SetCallbacks(app.notifyPeerOnline, app.notifyPeerOffline)

	// 12. 启动 discovery
	if err := discovery.Start(); err != nil {
		fmt.Printf("[LanChat] 启动发现服务失败: %v\n", err)
		fmt.Println("（可能端口被占用？程序将继续运行，但无法发现或被发现）")
	}

	// 13. 启动探活 goroutine
	go app.probeSavedContactsLoop()

	// 14. 设置路由
	mux := http.NewServeMux()

	// 静态文件
	staticDir := http.Dir("./static")
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServer(staticDir)))

	// 首页
	mux.HandleFunc("GET /", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		http.ServeFile(w, r, "./static/index.html")
	})

	// REST API
	app.registerHandlers(mux)

	// 文件传输 API
	app.registerTransferHandlers(mux)

	// WebSocket
	app.registerWSHandlers(mux)

	// CORS 中间件
	handler := corsMiddleware(mux)

	// 15. 启动 HTTP 服务器
	addr := fmt.Sprintf("0.0.0.0:%d", wsPort)
	server := &http.Server{
		Addr:         addr,
		Handler:      handler,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	// 优雅关闭
	go func() {
		sigChan := make(chan os.Signal, 1)
		signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
		<-sigChan
		fmt.Println("\n[LanChat] 正在关闭...")
		discovery.Stop()
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		server.Shutdown(ctx)
	}()

	fmt.Printf("[LanChat] 已启动: http://localhost:%d\n", wsPort)
	if err := server.ListenAndServe(); err != http.ErrServerClosed {
		fmt.Printf("[LanChat] 服务器错误: %v\n", err)
	}
	fmt.Println("[LanChat] 已停止")
}

// probeSavedContactsLoop 定期 HTTP 探活（每30秒）
func (app *AppState) probeSavedContactsLoop() {
	time.Sleep(3 * time.Second) // 等 UDP 广播先跑一轮
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		app.probeSavedContacts()
	}
}

// ============================================================
// 网络工具函数
// ============================================================

// getLocalIP 获取本机局域网 IP
func getLocalIP() string {
	// 方法1：通过连接外网获取
	conn, err := net.Dial("udp", "8.8.8.8:80")
	if err == nil {
		ip, _, _ := net.SplitHostPort(conn.LocalAddr().String())
		conn.Close()
		if ip != "127.0.0.1" {
			return ip
		}
	}

	// 方法2：枚举网卡
	addrs, err := net.InterfaceAddrs()
	if err == nil {
		for _, addr := range addrs {
			if ipNet, ok := addr.(*net.IPNet); ok && !ipNet.IP.IsLoopback() && ipNet.IP.To4() != nil {
				ip := ipNet.IP.String()
				if !strings.HasPrefix(ip, "169.254.") {
					return ip
				}
			}
		}
	}

	// 方法3：getaddrinfo
	hostname, _ := os.Hostname()
	ips, _ := net.LookupIP(hostname)
	for _, ip := range ips {
		if ipv4 := ip.To4(); ipv4 != nil && !ipv4.IsLoopback() {
			ipStr := ipv4.String()
			if !strings.HasPrefix(ipStr, "169.254.") {
				return ipStr
			}
		}
	}

	return "127.0.0.1"
}

// findAvailablePort 从 start 开始查找可用端口
func findAvailablePort(start, maxTries int) int {
	for offset := 0; offset < maxTries; offset++ {
		port := start + offset
		addr := fmt.Sprintf("0.0.0.0:%d", port)
		listener, err := net.Listen("tcp", addr)
		if err == nil {
			listener.Close()
			return port
		}
	}
	return start
}

// getNetworkSegment 计算网段 a.b.c.0/24
func getNetworkSegment(ip string) string {
	parts := strings.Split(ip, ".")
	if len(parts) == 4 {
		return parts[0] + "." + parts[1] + "." + parts[2] + ".0/24"
	}
	return "0.0.0.0/24"
}

// generateUUID12 生成 12 字符 hex UUID
func generateUUID12() string {
	b := make([]byte, 6)
	// 简单随机生成
	for i := range b {
		b[i] = byte(time.Now().UnixNano()>>(i*8)) ^ byte(i*127)
	}
	return fmt.Sprintf("%x", b)
}

// ============================================================
// CORS 中间件
// ============================================================

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "*")
		w.Header().Set("Access-Control-Allow-Methods", "*")

		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}

		next.ServeHTTP(w, r)
	})
}

